using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "SoulHeatBasedCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/SoulHeatBasedCustomDescription", order = 0)]
public class SoulHeatBasedCustomDescription : CustomBattleActionDescription
{
	private const string dontBreakChantingID = "DontBreakChanting";

	protected const string soulHeatBasedActionMultiplierID = "SoulHeatBasedActionMultiplier";

	private const string resetCorruptedSoulID = "ResetCorruptedSoul";

	public string DontBreakChantingID => "DontBreakChanting";

	public string SoulHeatBasedActionMultiplierID => "SoulHeatBasedActionMultiplier";

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		SoulHeatBasedAction soulHeatBasedAction = battleAction as SoulHeatBasedAction;
		string text = "";
		if (soulHeatBasedAction.IsEvilSoulHeatBased)
		{
			text = soulHeatBasedAction.BattleAction.GetActionDescription(1);
			return Smart.Format(base.localizationManager.GetLocalizedForEach(), text.RemoveLastIfNotJapaneseNorKoreanNorTraditionalChinese(), GetRawLocalizedDescription(battleAction)) + "\n" + base.localizationManager.GetLocalizedString("ResetCorruptedSoul");
		}
		string localizedString = base.localizationManager.GetLocalizedString("SoulHeatBasedActionMultiplier");
		text = soulHeatBasedAction.BattleAction.GetActionDescription(GetAmountWithoutEquation(amountModified), GetBonusAmountWithoutEquation(amountModified));
		return Smart.Format(base.localizationManager.GetLocalizedForEach(), text.RemoveLastIfNotJapaneseNorKoreanNorTraditionalChinese(), localizedString);
	}
}
